import base64
from pathlib import Path

def replace_arquivo_inteiro(caminho, old_b64, new_b64, label):
    p = Path(caminho)
    if not p.exists():
        raise SystemExit(f"ABORTADO ({label}): arquivo {caminho} nao encontrado. Rode na raiz do projeto denise-os.")
    atual = p.read_bytes()
    esperado_antigo = base64.b64decode(old_b64)
    if atual != esperado_antigo:
        raise SystemExit(f"ABORTADO ({label}): o conteudo atual de {caminho} nao bate com o esperado. Nada foi alterado (proteção contra sobrescrever mudanças que voce nao me contou).")
    novo = base64.b64decode(new_b64)
    p.write_bytes(novo)
    print(f"OK ({label}): {caminho} atualizado.")

OLD_MAIN_TSX = ""
NEW_MAIN_TSX = ""

replace_arquivo_inteiro("src/main.tsx", OLD_MAIN_TSX, NEW_MAIN_TSX, "saude-header-datanav-domi-derick")

